const fs = require('fs');
const buf = fs.readFileSync('/workspace/world.db');
const text = buf.toString('utf8');

// Find PROD-FA0948 and PROD-B98D14 regions
const ids = ['PROD-FA0948', 'PROD-B98D14'];
for (const id of ids) {
  let idx = 0;
  while ((idx = text.indexOf(id, idx)) !== -1) {
    const start = Math.max(0, idx - 200);
    const end = Math.min(buf.length, idx + 500);
    const snippet = buf.toString('utf8', start, end).replace(/[^\x20-\x7E\n\r]/g, '|');
    console.log('=== Found', id, 'at offset', idx, '===');
    console.log(snippet);
    console.log('');
    idx += id.length;
  }
}
