node -e "
const Database = require('better-sqlite3');
const db = new Database('/workspace/world.db');

const cartId = 'CART-user_d3d5d0c8';
const customerId = 'user_d3d5d0c8';
const productId = 'PROD-FA0948';
const newItemId = 'CI-0035';

// Check the product isn't already in the cart
const existing = db.prepare('SELECT * FROM cart_items WHERE cart_id = ? AND product_id = ?').get(cartId, productId);
if (existing) {
  console.log('Product already in cart!');
  process.exit(0);
}

// Get product price
const product = db.prepare('SELECT price, current_price FROM products WHERE product_id = ?').get(productId);
const price = product.current_price || product.price;
console.log('Product price:', price);

// Insert cart item
db.prepare('INSERT INTO cart_items (cart_item_id, cart_id, customer_id, product_id, quantity, gift_wrap) VALUES (?, ?, ?, ?, 1, 0)')
  .run(newItemId, cartId, customerId, productId);

// Update cart: add item to item_ids_json, update subtotal and total
const cart = db.prepare('SELECT * FROM carts WHERE cart_id = ?').get(cartId);
const itemIds = JSON.parse(cart.item_ids_json);
itemIds.push(newItemId);

const newSubtotal = cart.subtotal + price;
const newTotal = newSubtotal - cart.discount_amount + cart.gift_wrap_fee - cart.loyalty_discount + cart.shipping_cost;

db.prepare('UPDATE carts SET subtotal = ?, total = ?, item_ids_json = ? WHERE cart_id = ?')
  .run(newSubtotal, newTotal, JSON.stringify(itemIds), cartId);

// Verify
const updatedCart = db.prepare('SELECT * FROM carts WHERE cart_id = ?').get(cartId);
const updatedItems = db.prepare('SELECT ci.*, p.name, p.price FROM cart_items ci JOIN products p ON ci.product_id = p.product_id WHERE ci.cart_id = ?').all(cartId);

console.log();
console.log('Updated cart:', JSON.stringify(updatedCart, null, 2));
console.log();
console.log('Cart items:', JSON.stringify(updatedItems, null, 2));
"
